/bin/bash -lc "python3 - <<'PY'
import subprocess
commit='d1a334ef26674792d33b6cfe1be97f4e844673b5'
for name in ('OPEN_QUESTIONS.md', 'DECISIONS.md', 'PLANNING_KERNEL_CONTRACT.md'):
    contents=subprocess.check_output(['git','show',f'{commit}:{name}'],text=True)
    lines=contents.splitlines()
    if name=='OPEN_QUESTIONS.md':
        start=next(i for i,l in enumerate(lines) if l.startswith('## UBU-Q0112:'))
        end=next(i for i in range(start+1,len(lines)) if lines[i].startswith('## UBU-Q'))
        selected=range(start-2,end+2)
    elif name=='DECISIONS.md':
        selected=range(max(0,len(lines)-165),len(lines))
    else:
        selected=range(len(lines))
    print(f'FILE {name}')
    for i in selected:
        print(f'{i+1}: {lines[i]}')
PY"

